(function(){window.ACADEMIA_RUTAS=[{id:"b0",etiqueta:"Bloque 0",titulo:"Empieza aquí",icono:"ri-flag-line",descripcion:"Qué vas a conseguir, cómo funciona la Academia, tu panel de To Growth y tu copiloto de IA preparado con los datos de tu negocio."},{id:"b1",etiqueta:"Bloque 1",titulo:"La base de tu negocio",icono:"ri-compass-3-line",descripcion:"A quién le vendes, qué le ofreces, cuánto cobras y la imagen mínima para dar confianza. Sin esto, ninguna técnica funciona."},{id:"b2",etiqueta:"Bloque 2",titulo:"Captar clientes sin presupuesto",icono:"ri-phone-find-line",descripcion:"Tu lista de empresas, la llamada, el email, LinkedIn, WhatsApp, vídeos y directos, y que te encuentren en Google. Solo hace falta tiempo."},{id:"b3",etiqueta:"Bloque 3",titulo:"Captar clientes con presupuesto",icono:"ri-advertisement-line",descripcion:"Cuándo meter dinero y cómo: campañas de email a muchas empresas, anuncios en Meta y en Google, páginas y embudos."},{id:"b4",etiqueta:"Bloque 4",titulo:"Vender: la reunión y el cierre",icono:"ri-shake-hands-line",descripcion:"De la primera reunión al sí: preparar, preguntar, proponer, responder a las dudas y cobrar."},{id:"b5",etiqueta:"Bloque 5",titulo:"Entregar y fidelizar",icono:"ri-heart-3-line",descripcion:"Que el cliente se quede, te compre más y te recomiende."},{id:"b6",etiqueta:"Bloque 6",titulo:"Escalar",icono:"ri-line-chart-line",descripcion:"Tus números, tu sistema, tu primer equipo y el paso de trabajar solo a una agencia pequeña."},{id:"bx",etiqueta:"Extra",titulo:"Servicios que puedes vender",icono:"ri-store-2-line",descripcion:"Si todavía no sabes qué vender: nueve servicios que los negocios necesitan, cada uno con cómo se hace con IA, cómo venderlo y cómo entregarlo."}],window.ACADEMIA_MODULOS=[{id:"m0",ruta:"b0",number:"Módulo 0",icon:"ri-flag-line",title:"Bienvenida y método",description:"Sabes qué vas a aprender, en qué orden y con qué herramientas. Terminas con tu panel de To Growth conocido y con Claude preparado con los datos de tu negocio.",disponible:"2026-10-19",lessons:[{id:"m0_l1",title:"0.1 Bienvenida: qué vas a conseguir aquí",duration:"6 min",tipo:"C",ia:!1,summary:"Te cuento para quién es esta Academia y qué vas a saber hacer al terminarla. La idea es sencilla: elegir a quién le vendes, conseguir su contacto y hablar con él hasta que haya una reunión. Aquí no hay atajos: hay un método y hay que hacerlo.",keyTakeaways:["Sabrás explicar el método en tres pasos: a quién, qué le ofreces y cómo le contactas.","Sabrás qué puedes esperar de la Academia y qué depende solo de ti.","Sabrás por dónde empezar hoy mismo."],video:null},{id:"m0_l2",title:"0.2 El mapa de la Academia: sin presupuesto, con presupuesto, vender, entregar, escalar",duration:"7 min",tipo:"C",ia:!1,summary:"Repasas los bloques de la Academia uno a uno, como quien mira el plano antes de un viaje. Ves qué se aprende en cada bloque y cuál te toca según tu momento. Así no te pierdes ni saltas a lo que todavía no necesitas.",keyTakeaways:["Sabrás qué hay en cada bloque y para qué sirve.","Sabrás distinguir entre captar clientes sin gastar dinero y captar con anuncios.","Sabrás qué módulos hacer primero si empiezas de cero."],video:null},{id:"m0_l3",title:"0.3 Tu panel de To Growth en 10 minutos",duration:"10 min",tipo:"P",ia:!1,summary:"Recorres el panel de To Growth pantalla a pantalla: el Buscador de empresas, las Listas guardadas, el Organizador de llamadas, los Guiones guardados y Mi perfil. Rellenas tu perfil, porque de ahí salen los guiones. Y conoces el botón azul del Asistente To Growth.",keyTakeaways:["Sabrás moverte por el menú sin perderte.","Sabrás rellenar Mi perfil para que los guiones hablen de tu negocio.","Sabrás abrir el Asistente To Growth y pedirle ayuda."],video:null},{id:"m0_l4",title:"0.4 Tu copiloto: prepara Claude con los datos de tu negocio",duration:"9 min",tipo:"P",ia:!0,summary:"Creas un Proyecto en Claude y le pegas las instrucciones y los datos de tu negocio: qué vendes, a quién y cómo hablas. Desde ese momento Claude te ayuda sin que tengas que explicárselo todo cada vez. Si tu plan no tiene Proyectos, pegas ese texto al empezar cada conversación; con ChatGPT o Gemini sirve igual.",keyTakeaways:["Sabrás crear un Proyecto en Claude con las instrucciones copiadas y pegadas.","Sabrás rellenar los huecos con los datos de tu negocio.","Sabrás que la IA se equivoca y que siempre revisas lo que escribe."],video:null},{id:"m0_l5",title:"0.5 Tu compromiso de trabajo y cómo usar la comunidad",duration:"6 min",tipo:"C",ia:!1,summary:"Te propongo un plan de trabajo claro: diez contactos al día, cinco días a la semana, seis semanas. Te explico por qué la constancia importa más que el talento, igual que en el gimnasio. Y ves cómo usar la pestaña Comunidad para presentarte, preguntar y contar lo que haces.",keyTakeaways:["Sabrás cuánto trabajo hacer cada día y cuándo hacerlo.","Sabrás apuntar tu compromiso para cumplirlo.","Sabrás presentarte en la comunidad y pedir ayuda cuando te atasques."],video:null}]},{id:"m1",ruta:"b1",number:"Módulo 1",icon:"ri-focus-3-line",title:"A quién le vendes",description:"Eliges un tipo de cliente concreto: qué negocio, de qué tamaño y en qué zona. Terminas sabiendo qué problema tiene, quién decide dentro y por qué te va a escuchar.",disponible:"2026-10-26",lessons:[{id:"m1_l1",title:"1.1 Por qué esperar a que te recomienden no es un plan",duration:"7 min",tipo:"C",ia:!1,summary:"Las recomendaciones están muy bien, pero no las controlas tú. Es como esperar a que suene el teléfono: puede sonar o no. Aquí entiendes por qué necesitas una forma de buscar clientes que dependa de ti.",keyTakeaways:["Sabrás por qué depender solo de recomendaciones te deja meses sin trabajo.","Sabrás la diferencia entre esperar clientes e ir a buscarlos.","Sabrás qué significa tener un sistema para conseguir clientes."],video:null},{id:"m1_l2",title:"1.2 Elegir un tipo de cliente: negocio, tamaño y zona",duration:"8 min",tipo:"C",ia:!1,summary:"Eliges a quién le vas a vender con tres decisiones: qué tipo de negocio, de qué tamaño y en qué zona. Por ejemplo, clínicas dentales pequeñas de Valencia. Cuanto más concreto, más fácil es encontrarlos y saber qué decirles.",keyTakeaways:["Sabrás elegir un tipo de negocio al que venderle.","Sabrás decidir el tamaño y la zona para empezar.","Sabrás escribir tu tipo de cliente en una sola frase."],video:null},{id:"m1_l3",title:"1.3 El problema que les cuesta dinero",duration:"7 min",tipo:"C",ia:!1,summary:"Un negocio no te compra un servicio: te paga por quitarle un problema. Aprendes a encontrar el problema que a tu cliente le cuesta dinero cada mes, como sillones vacíos en una clínica o mesas sin llenar en un restaurante. Ese problema es de lo que vas a hablar cuando le contactes.",keyTakeaways:["Sabrás encontrar el problema que más le duele a tu tipo de cliente.","Sabrás explicar ese problema con sus palabras, no con las tuyas.","Sabrás poner un ejemplo sencillo de lo que pierde por no arreglarlo."],video:null},{id:"m1_l4",title:"1.4 Quién decide y quién paga dentro de una empresa",duration:"6 min",tipo:"C",ia:!1,summary:"En un negocio pequeño casi siempre decide el dueño. En uno más grande hay una persona que coge el teléfono, otra que opina y otra que firma. Aprendes a saber con quién tienes que hablar para no perder semanas con quien no decide.",keyTakeaways:["Sabrás quién suele decir que sí según el tamaño del negocio.","Sabrás pedir que te pasen con esa persona sin ser pesado.","Sabrás reconocer cuándo hablas con alguien que no decide."],video:null},{id:"m1_l5",title:"1.5 Investiga tu tipo de cliente en 20 minutos con Claude",duration:"9 min",tipo:"P",ia:!0,summary:"Pegas una instrucción en Claude y le preguntas por tu tipo de cliente: cómo gana dinero, qué le preocupa y qué palabras usa. En veinte minutos tienes un resumen que te habría costado días. Después lo revisas, porque Claude puede equivocarse, y te quedas con lo que te sirve.",keyTakeaways:["Sabrás pedirle a Claude un resumen claro de tu tipo de cliente.","Sabrás sacar de ahí sus problemas y sus palabras.","Sabrás comprobar lo que dice la IA antes de darlo por bueno."],video:null}]},{id:"m2",ruta:"b1",number:"Módulo 2",icon:"ri-price-tag-3-line",title:"Tu oferta y tu precio",description:"Conviertes lo que sabes hacer en una oferta clara, con un precio que sabes defender. Terminas con tu oferta escrita en una frase y probada con diez personas.",disponible:"2026-10-26",lessons:[{id:"m2_l1",title:'2.1 Qué es una oferta (y por qué "hago webs" no lo es)',duration:"7 min",tipo:"C",ia:!1,summary:"«Hago webs» dice lo que haces tú, no lo que gana el otro. Una oferta dice para quién es, qué consigue y en cuánto tiempo. Si todavía no sabes qué vender, aquí te mando al bloque extra «Servicios que puedes vender».",keyTakeaways:["Sabrás distinguir entre un servicio y una oferta.","Sabrás las tres piezas de una oferta: para quién, qué consigue y cuándo.","Sabrás dónde ir si aún no tienes un servicio que vender."],video:null},{id:"m2_l2",title:"2.2 De lo que sabes hacer a una oferta en una frase",duration:"8 min",tipo:"C",ia:!1,summary:"Partes de lo que ya sabes hacer y lo conviertes en una frase que cualquiera entiende a la primera. Usas una plantilla muy sencilla y la rellenas con tu tipo de cliente y su problema. Sales con tu oferta escrita.",keyTakeaways:["Sabrás rellenar la plantilla de la oferta con tus datos.","Sabrás decir tu oferta en voz alta en diez segundos.","Sabrás quitarle las palabras raras para que se entienda."],video:null},{id:"m2_l3",title:"2.3 Cuánto cobrar: barato, medio y caro",duration:"8 min",tipo:"C",ia:!1,summary:"Poner precio da miedo, y por eso casi todo el mundo empieza cobrando de menos. Ves tres formas de cobrar, barato, medio y caro, y qué pasa con cada una. Eliges tu precio de salida haciendo una cuenta sencilla con tus horas y tus gastos.",keyTakeaways:["Sabrás calcular tu precio mínimo con una cuenta sencilla.","Sabrás qué tipo de cliente atrae cada nivel de precio.","Sabrás decir tu precio sin pedir perdón."],video:null},{id:"m2_l4",title:"2.4 Paquetes y cuota mensual: cómo cobrar todos los meses",duration:"8 min",tipo:"C",ia:!1,summary:"Cobrar una sola vez te obliga a empezar de cero cada mes. Aprendes a ofrecer tu trabajo en dos o tres paquetes y a ponerle una cuota mensual, como la del gimnasio. Así el cliente elige entre opciones tuyas y tú sabes lo que entra cada mes.",keyTakeaways:["Sabrás montar dos o tres paquetes con lo que incluye cada uno.","Sabrás convertir un trabajo suelto en un servicio mensual.","Sabrás explicar al cliente qué recibe cada mes por su cuota."],video:null},{id:"m2_l5",title:"2.5 Escribe y mejora tu oferta con Claude",duration:"8 min",tipo:"P",ia:!0,summary:"Le das a Claude tu oferta tal como la tienes y le pides que la critique como si fuera tu cliente. Te devuelve versiones más claras y las pegas que le pondría un dueño de negocio. Tú eliges la que suena a ti y la corriges a mano.",keyTakeaways:["Sabrás pedirle a Claude cinco versiones de tu oferta.","Sabrás usar a Claude para encontrar los puntos flojos.","Sabrás quedarte con una versión y dejarla con tus palabras."],video:null},{id:"m2_l6",title:"2.6 Pruébala con 10 personas antes de darla por buena",duration:"6 min",tipo:"C",ia:!1,summary:"Una oferta no es buena porque te guste a ti: es buena si la entiende quien la tiene que comprar. Se la enseñas a diez personas de tu tipo de cliente y apuntas qué preguntan y dónde se pierden. Con eso la ajustas antes de salir a vender.",keyTakeaways:["Sabrás a quién enseñarle tu oferta y qué preguntarle.","Sabrás apuntar las dudas que se repiten.","Sabrás cambiar tu oferta con lo que has escuchado."],video:null}]},{id:"m3",ruta:"b1",number:"Módulo 3",icon:"ri-user-star-line",title:"Tu imagen profesional (en una tarde)",description:"Dejas listo lo mínimo para que un negocio se fíe de ti cuando te busque: correo con tu nombre, una web de una página y tus perfiles en orden. Todo en una tarde, sin gastar de más.",disponible:"2026-11-02",lessons:[{id:"m3_l1",title:"3.1 Lo mínimo que necesitas (y lo que puede esperar)",duration:"6 min",tipo:"C",ia:!1,summary:"Mucha gente pasa meses con el logo y la web, y no llama a nadie. Aquí separas lo que hace falta de verdad para empezar de lo que puede esperar. Te llevas una lista corta para hacer en una tarde.",keyTakeaways:["Sabrás qué cuatro cosas necesitas antes de contactar a nadie.","Sabrás qué puedes dejar para más adelante sin que pase nada.","Sabrás no usar la imagen como excusa para no vender."],video:null},{id:"m3_l2",title:"3.2 Dominio y correo con tu nombre",duration:"8 min",tipo:"P",ia:!1,summary:"Compras tu dominio, que es tu dirección en internet, y creas un correo con tu nombre en vez de uno gratuito. Lo ves paso a paso en pantalla. Un correo propio da más confianza que uno de los de toda la vida.",keyTakeaways:["Sabrás elegir y comprar un dominio para tu negocio.","Sabrás crear un correo con tu nombre y tu dominio.","Sabrás poner una firma sencilla con tus datos."],video:null},{id:"m3_l3",title:"3.3 Tu web de una página, hecha con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Con Claude escribes y montas una web de una sola página: qué haces, para quién y cómo contactarte. Le pegas la instrucción con tu oferta y él te da los textos y la página. Tú lo revisas todo, corriges lo que no sea verdad y la publicas.",keyTakeaways:["Sabrás pedirle a Claude los textos de tu web con tu oferta.","Sabrás qué apartados lleva una web de una página.","Sabrás revisar y corregir lo que escribe la IA antes de publicarlo."],video:null},{id:"m3_l4",title:"3.4 LinkedIn, Instagram y ficha de Google listos para dar confianza",duration:"9 min",tipo:"P",ia:!1,summary:"Cuando llamas a un negocio, lo primero que hace es buscarte. Dejas tu LinkedIn, tu Instagram y tu ficha de Google con foto, una frase clara y la forma de contactarte. No hace falta publicar cada día: hace falta que se vea que eres de verdad.",keyTakeaways:["Sabrás poner una foto y una frase clara en cada perfil.","Sabrás qué enlaces y datos de contacto dejar a la vista.","Sabrás repasar tus perfiles como los vería un cliente."],video:null},{id:"m3_l5",title:"3.5 Qué enseñar cuando todavía no tienes casos",duration:"7 min",tipo:"C",ia:!1,summary:"Todo el mundo empieza sin clientes que enseñar. Ves qué puedes mostrar sin mentir: un trabajo de muestra, un ejemplo hecho para un negocio real o lo que has hecho en otros trabajos. Y aprendes a decirlo con naturalidad cuando te pregunten.",keyTakeaways:["Sabrás preparar un trabajo de muestra para enseñar.","Sabrás contar tu experiencia sin inventar nada.","Sabrás responder a «¿con quién has trabajado?» con tranquilidad."],video:null}]},{id:"m4",ruta:"b2",number:"Módulo 4",icon:"ri-list-check-2",title:"Tu lista de empresas",description:"Sacas de To Growth una lista de empresas reales de tu tipo de cliente, con su teléfono y el motivo para contactarlas. Terminas con tus 20 primeras guardadas y preparadas.",disponible:"2026-10-19",lessons:[{id:"m4_l1",title:"4.1 El buscador: sector, ciudad y empresas reales con teléfono",duration:"8 min",tipo:"P",ia:!1,summary:"Abres el Buscador de empresas, escribes el sector y la ciudad y pulsas «Buscar empresas». Salen negocios reales de Google Maps con su teléfono, su web, su valoración y sus reseñas. Haces tu primera búsqueda y aprendes a leer cada tarjeta.",keyTakeaways:["Sabrás hacer una búsqueda con «Sector o tipo de negocio» y «Ciudad o zona».","Sabrás leer los datos de la tarjeta de cada empresa.","Sabrás cambiar el sector o la zona si salen pocos resultados."],video:null},{id:"m4_l2",title:"4.2 Las señales de oportunidad: sin web, reseñas flojas, valoración baja",duration:"8 min",tipo:"P",ia:!1,summary:"Cada tarjeta trae etiquetas que te dan el motivo para contactar: «Sin web», «Pocas reseñas», «Valoración» con su nota o «Negocio consolidado». Aprendes qué significa cada una y a cuáles ir primero. Con el desplegable de resultados las ves ordenadas por oportunidad.",keyTakeaways:["Sabrás qué te dice cada etiqueta de una empresa.","Sabrás ordenar y filtrar los resultados por oportunidad.","Sabrás convertir una etiqueta en un motivo para llamar."],video:null},{id:"m4_l3",title:"4.3 El Buscador Pro: empresas que no salen en Google Maps",duration:"9 min",tipo:"P",ia:!1,summary:"El Buscador Pro encuentra empresas con oficina y empleados que no suelen salir en Google Maps, con su web, su teléfono, su sector y su tamaño. Conectas tu cuenta gratuita de Apollo en «Ajustes e integraciones», paso a paso. Y aprendes tres caminos para dar con la persona que decide.",keyTakeaways:["Sabrás conectar tu cuenta gratuita de Apollo en Ajustes e integraciones.","Sabrás encontrar a la persona que decide con el botón «Buscar responsable».","Sabrás elegir entre el Buscador normal y el Pro según a quién vendes."],video:null},{id:"m4_l4",title:"4.4 Guardar, ordenar y preparar tus 20 primeras",duration:"8 min",tipo:"P",ia:!1,summary:"Pulsas «Guardar» en las empresas que te interesan y aparecen en «Listas guardadas» y en el Organizador de llamadas. Eliges tus veinte primeras empezando por las que tienen mejor motivo para contactar. Sales con la lista hecha para empezar a llamar mañana.",keyTakeaways:["Sabrás guardar empresas y encontrarlas en Listas guardadas.","Sabrás elegir cuáles van primero y por qué.","Sabrás dejar preparadas veinte empresas para contactar."],video:null},{id:"m4_l5",title:"4.5 Claude analiza cada empresa y te dice por dónde entrar",duration:"9 min",tipo:"P",ia:!0,summary:"Copias los datos de una empresa de tu lista y se los pegas a Claude con la instrucción del episodio. Te devuelve qué ha visto, qué problema puede tener y una frase para abrir la conversación. Lo compruebas con tus ojos antes de usarlo, porque la IA puede equivocarse.",keyTakeaways:["Sabrás pasarle a Claude los datos de una empresa.","Sabrás sacar un motivo concreto para contactar a cada una.","Sabrás revisar lo que dice Claude antes de llamar."],video:null}]},{id:"m5",ruta:"b2",number:"Módulo 5",icon:"ri-phone-line",title:"La llamada",description:"Pierdes el miedo a llamar y aprendes la llamada de principio a fin: cómo abrir, qué preguntar, qué responder a un no y cómo pedir la reunión. Terminas con tu guion y habiéndolo ensayado.",disponible:"2026-10-19",lessons:[{id:"m5_l1",title:"5.1 El miedo a llamar: qué pasa de verdad cuando marcas",duration:"7 min",tipo:"C",ia:!1,summary:"El miedo a llamar es normal: lo tiene todo el mundo el primer día. Te cuento qué pasa de verdad cuando marcas: muchos no cogen, algunos dicen que no y unos pocos te escuchan. Cuando lo sabes de antemano, deja de asustar.",keyTakeaways:["Sabrás qué respuestas son normales al llamar a un negocio.","Sabrás que un no es parte del trabajo y no va contra ti.","Sabrás hacer tu primera llamada aunque tengas nervios."],video:null},{id:"m5_l2",title:"5.2 Los primeros 15 segundos",duration:"8 min",tipo:"C",ia:!1,summary:"En los primeros quince segundos la otra persona decide si te escucha o cuelga. Aprendes a decir quién eres, por qué llamas y a pedir permiso para seguir. Lo oyes en un ejemplo completo, dicho en voz alta.",keyTakeaways:["Sabrás presentarte en una frase.","Sabrás pedir treinta segundos sin sonar a vendedor.","Sabrás qué decir si te coge alguien que no es el dueño."],video:null},{id:"m5_l3",title:"5.3 El motivo de la llamada y las dos preguntas",duration:"8 min",tipo:"C",ia:!1,summary:"Una llamada funciona cuando tienes un motivo concreto de esa empresa, por ejemplo que no tiene web. Después haces dos preguntas y dejas hablar al otro. Quien pregunta bien no necesita soltar un discurso.",keyTakeaways:["Sabrás decir el motivo de tu llamada en una frase.","Sabrás hacer dos preguntas que hacen hablar al dueño.","Sabrás escuchar y apuntar lo que te cuenta."],video:null},{id:"m5_l4",title:"5.4 El guion con IA para cada empresa, dentro de To Growth",duration:"8 min",tipo:"P",ia:!0,summary:"En cada empresa tienes el botón «Guion IA». La IA escribe un guion de llamada para esa empresa con los datos de Mi perfil: la apertura, el motivo, las dos preguntas y qué responder a la pega más habitual. Lo lees, lo ajustas a tu forma de hablar y lo guardas.",keyTakeaways:["Sabrás generar un guion para una empresa concreta.","Sabrás mejorar el guion rellenando bien Mi perfil.","Sabrás retocarlo para que suene a ti antes de llamar."],video:null},{id:"m5_l5",title:"5.5 Qué responder cuando te dicen que no",duration:"9 min",tipo:"C",ia:!1,summary:"«Ya tengo a alguien», «mándame un correo», «ahora no es el momento», «no me interesa». Casi siempre son las mismas frases, así que puedes llevar la respuesta preparada. Aprendes una respuesta tranquila para cada una y cuándo toca dar las gracias y colgar.",keyTakeaways:["Sabrás responder a las cinco pegas más habituales.","Sabrás hacer una pregunta más sin insistir de más.","Sabrás cuándo dejarlo y pasar a la siguiente empresa."],video:null},{id:"m5_l6",title:"5.6 Pedir la reunión y confirmarla",duration:"7 min",tipo:"C",ia:!1,summary:"El objetivo de la llamada no es vender: es quedar para hablar con calma. Aprendes a proponer dos días y horas concretos, en vez de preguntar cuándo le viene bien. Y a confirmar la reunión por escrito para que no se le olvide.",keyTakeaways:["Sabrás pedir la reunión dando dos opciones de día y hora.","Sabrás enviar un mensaje corto para confirmarla.","Sabrás mover la empresa a «Reunión agendada» en el Organizador."],video:null},{id:"m5_l7",title:"5.7 Ensaya con Claude haciendo de cliente difícil",duration:"9 min",tipo:"P",ia:!0,summary:"Le pides a Claude que haga de dueño de un negocio con prisa y pocas ganas de hablar. Tú escribes lo que dirías y él te responde como respondería ese dueño. Al terminar le pides que te diga qué has hecho bien y qué puedes mejorar.",keyTakeaways:["Sabrás montar un ensayo de llamada con Claude.","Sabrás practicar las pegas hasta que no te pillen por sorpresa.","Sabrás pedirle a Claude una corrección clara de tu llamada."],video:null}]},{id:"m6",ruta:"b2",number:"Módulo 6",icon:"ri-mail-send-line",title:"Email y mensajes uno a uno",description:"Aprendes a escribir a un negocio un mensaje corto que se lee y se contesta. Terminas con tus tres correos preparados y sabiendo qué hacer con cada respuesta.",disponible:"2026-10-26",lessons:[{id:"m6_l1",title:"6.1 Cuándo llamar y cuándo escribir",duration:"6 min",tipo:"C",ia:!1,summary:"Llamar y escribir no compiten: se ayudan. Ves en qué casos conviene más cada cosa, según el tipo de negocio y el dato de contacto que tengas. Y cómo combinar una llamada y un correo con la misma empresa.",keyTakeaways:["Sabrás decidir si llamas o escribes a cada empresa.","Sabrás combinar llamada y correo sin resultar pesado.","Sabrás qué hacer cuando solo tienes un teléfono o solo un email."],video:null},{id:"m6_l2",title:"6.2 El mensaje de 4 frases",duration:"8 min",tipo:"C+P",ia:!1,summary:"Un correo largo no se lee. Aprendes un mensaje de cuatro frases: por qué le escribes a él, qué has visto, qué le propones y una pregunta fácil de contestar. Lo escribes en pantalla con una empresa de ejemplo.",keyTakeaways:["Sabrás escribir un mensaje de cuatro frases para un negocio.","Sabrás poner un asunto corto que no suene a publicidad.","Sabrás terminar con una pregunta que se contesta con un sí o un no."],video:null},{id:"m6_l3",title:"6.3 La secuencia de 3 correos",duration:"9 min",tipo:"P",ia:!1,summary:"Casi nadie contesta al primer correo, y no pasa nada. Preparas tres correos seguidos: el primero, un recordatorio corto y una despedida amable. Los escribes en pantalla y los envías tú desde tu correo, uno a uno, con unos días entre cada uno.",keyTakeaways:["Sabrás escribir tus tres correos para la misma empresa.","Sabrás cuántos días dejar entre un correo y el siguiente.","Sabrás parar de escribir cuando te contestan o te dicen que no."],video:null},{id:"m6_l4",title:"6.4 Personaliza 20 correos en 10 minutos con Claude",duration:"9 min",tipo:"P",ia:!0,summary:"Le pasas a Claude tu mensaje de cuatro frases y los datos de veinte empresas de tu lista. Te devuelve veinte correos, cada uno con una primera frase distinta para cada negocio. Claude no envía nada: tú los lees, corriges lo que no cuadre y los mandas.",keyTakeaways:["Sabrás pasarle a Claude tu lista de empresas con sus datos.","Sabrás conseguir una primera frase distinta para cada correo.","Sabrás revisar cada correo antes de enviarlo tú."],video:null},{id:"m6_l5",title:"6.5 ¿Es legal escribir a empresas en España?",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico con palabras normales qué dicen las normas sobre escribir a un negocio con el que no has hablado nunca. Ves las reglas que conviene cumplir siempre: decir quién eres, escribir a correos de empresa, dar una forma fácil de no recibir más y no insistir a quien dice que no. Es una explicación para orientarte; si tienes dudas con tu caso, consulta a un profesional.",keyTakeaways:["Sabrás qué conviene cumplir siempre que escribes a una empresa.","Sabrás qué correos puedes usar y cuáles es mejor evitar.","Sabrás qué hacer cuando alguien te pide que no le escribas más."],video:null},{id:"m6_l6",title:"6.6 Seguimiento: qué hacer con cada respuesta",duration:"8 min",tipo:"P",ia:!1,summary:"Cada respuesta pide una cosa distinta: un sí, un «ahora no», una pregunta o un silencio. Ves qué contestar en cada caso y cómo mover la ficha de la empresa de una columna a otra en el Organizador de llamadas. Así no se te olvida nadie.",keyTakeaways:["Sabrás qué contestar a cada tipo de respuesta.","Sabrás mover cada empresa a su columna en el Organizador.","Sabrás repasar el tablero para ver a quién toca escribir hoy."],video:null}]},{id:"m7",ruta:"b2",number:"Módulo 7",icon:"ri-chat-3-line",title:"LinkedIn, WhatsApp e Instagram",description:"Aprendes a empezar conversaciones por mensaje con quien decide en un negocio, sin sonar a anuncio. Terminas sabiendo qué canal usar con cada tipo de cliente y cómo pasar de un mensaje a una reunión.",disponible:"2026-11-09",lessons:[{id:"m7_l1",title:"7.1 LinkedIn: encontrar a quien decide y conectar",duration:"9 min",tipo:"P",ia:!1,summary:"Usas el buscador de LinkedIn para encontrar a la persona que decide en las empresas de tu lista. Le envías una invitación para conectar con una nota corta, sin vender nada. Lo ves paso a paso con un ejemplo.",keyTakeaways:["Sabrás buscar en LinkedIn por empresa, cargo y ciudad.","Sabrás escribir una nota de invitación corta.","Sabrás cuántas invitaciones enviar al día para ir con calma."],video:null},{id:"m7_l2",title:"7.2 La conversación en LinkedIn: hablar sin vender",duration:"8 min",tipo:"C+P",ia:!1,summary:"Cuando te aceptan, lo peor que puedes hacer es soltar tu oferta de golpe. Aprendes a empezar con una pregunta sobre su negocio y a seguir la conversación como la seguirías en persona. Ves una conversación entera de ejemplo, del saludo a proponer una llamada.",keyTakeaways:["Sabrás abrir una conversación con una pregunta sencilla.","Sabrás responder sin copiar y pegar el mismo texto a todos.","Sabrás proponer una llamada cuando hay interés."],video:null},{id:"m7_l3",title:"7.3 WhatsApp con negocios: qué se puede hacer y qué no",duration:"7 min",tipo:"C",ia:!1,summary:"WhatsApp es muy cercano, y por eso hay que usarlo con cuidado. Ves cuándo tiene sentido escribir a un negocio por WhatsApp y cuándo molesta. Y por qué mandar el mismo mensaje a muchos números a la vez es mala idea.",keyTakeaways:["Sabrás cuándo escribir por WhatsApp y cuándo no.","Sabrás escribir un primer mensaje corto y educado.","Sabrás evitar lo que hace que te bloqueen."],video:null},{id:"m7_l4",title:"7.4 Instagram: de un mensaje a una reunión",duration:"8 min",tipo:"C+P",ia:!1,summary:"Muchos negocios pequeños contestan antes en Instagram que por correo. Aprendes a mirar su perfil, comentar algo concreto y pasar a un mensaje privado. Ves el camino completo, del primer mensaje a quedar para hablar.",keyTakeaways:["Sabrás fijarte en un detalle del perfil para empezar.","Sabrás escribir un primer mensaje privado que no parece publicidad.","Sabrás llevar la conversación hasta proponer una reunión."],video:null},{id:"m7_l5",title:"7.5 Mensajes que no suenan a robot, con Claude",duration:"8 min",tipo:"P",ia:!0,summary:"Claude te ayuda a escribir mensajes para LinkedIn, WhatsApp e Instagram con tu forma de hablar. Le das tu oferta, el canal y dos o tres mensajes tuyos de ejemplo. Después quitas todo lo que suene a máquina y los envías tú, uno a uno.",keyTakeaways:["Sabrás enseñarle a Claude cómo escribes tú.","Sabrás pedirle mensajes cortos para cada canal.","Sabrás reconocer y quitar las frases que suenan a robot."],video:null}]},{id:"m8",ruta:"b2",number:"Módulo 8",icon:"ri-play-circle-line",title:"Contenido que trae clientes: vídeos y directos",description:"Aprendes a grabar vídeos y a hacer directos que enseñan lo que sabes y acercan a la gente a hablar contigo. Terminas con ideas para un mes y un calendario que puedes cumplir.",disponible:"2026-11-16",lessons:[{id:"m8_l1",title:"8.1 Por qué el contenido te trae clientes mientras duermes",duration:"7 min",tipo:"C",ia:!1,summary:"Una llamada la oye una persona. Un vídeo lo puede ver mucha gente, también cuando tú no estás trabajando. Entiendes cómo el contenido hace que te conozcan y se fíen de ti antes de hablar contigo, y por qué va despacio al principio.",keyTakeaways:["Sabrás para qué sirve el contenido dentro de tu forma de conseguir clientes.","Sabrás por qué tarda en notarse y hay que ser constante.","Sabrás combinarlo con las llamadas y los mensajes."],video:null},{id:"m8_l2",title:"8.2 Qué grabar: los 5 tipos de vídeo que funcionan para vender servicios",duration:"9 min",tipo:"C",ia:!1,summary:"No hace falta bailar ni contar tu vida. Ves cinco tipos de vídeo sencillos para quien vende servicios, cada uno con un ejemplo de un negocio normal. Eliges los dos que más van contigo para empezar.",keyTakeaways:["Sabrás los cinco tipos de vídeo y para qué sirve cada uno.","Sabrás empezar un vídeo con una frase que hace quedarse.","Sabrás elegir los dos tipos que te resultan más fáciles."],video:null},{id:"m8_l3",title:"8.3 Ideas y guiones para un mes con Claude",duration:"9 min",tipo:"P",ia:!0,summary:"Le das a Claude tu tipo de cliente y sus problemas, y le pides ideas de vídeo para un mes entero. De las mejores le pides un guion corto, escrito para decirlo en voz alta. Tú eliges, cambias lo que no sea verdad y lo dejas con tus palabras.",keyTakeaways:["Sabrás sacar con Claude una lista de ideas para un mes.","Sabrás pedir un guion corto para cada idea.","Sabrás adaptar cada guion a tu forma de hablar."],video:null},{id:"m8_l4",title:"8.4 Directos: cómo hacerlos y cómo llevar a la gente a una reunión",duration:"9 min",tipo:"C",ia:!1,summary:"En un directo la gente te ve tal como eres y te pregunta en el momento. Aprendes a prepararlo, de qué hablar y cómo contestar a quien escribe. Y cómo invitar, sin presionar, a quien quiera hablar contigo después.",keyTakeaways:["Sabrás preparar un directo con un tema y tres puntos.","Sabrás contestar preguntas sin perder el hilo.","Sabrás invitar a una reunión de forma natural."],video:null},{id:"m8_l5",title:"8.5 De un vídeo largo a diez cortos",duration:"8 min",tipo:"P",ia:!1,summary:"Grabar una vez y aprovecharlo muchas es lo que hace esto llevadero. Coges un vídeo largo o un directo y sacas diez trozos cortos, cada uno con una sola idea. Lo ves en pantalla, del vídeo entero a los cortes listos para subir.",keyTakeaways:["Sabrás encontrar los mejores momentos de un vídeo largo.","Sabrás cortar un trozo con una sola idea.","Sabrás poner un título y un texto en pantalla a cada corte."],video:null},{id:"m8_l6",title:"8.6 Tu calendario: cuánto publicar y dónde",duration:"6 min",tipo:"C",ia:!1,summary:"Es mejor publicar poco y siempre que mucho una semana y nada la siguiente. Decides cuántos vídeos subes a la semana y en qué red, según dónde está tu tipo de cliente. Te llevas un calendario sencillo que puedes cumplir.",keyTakeaways:["Sabrás elegir una o dos redes para empezar.","Sabrás cuántos vídeos publicar cada semana sin agobiarte.","Sabrás reservar un rato fijo para grabar."],video:null}]},{id:"m9",ruta:"b2",number:"Módulo 9",icon:"ri-google-line",title:"Que te encuentren en Google",description:"Preparas tu negocio para que aparezca cuando alguien busca lo que vendes, en Google y en las respuestas de las IA. Terminas con tu ficha de Google cuidada y tu primer contenido publicado.",disponible:"2026-11-23",lessons:[{id:"m9_l1",title:"9.1 Tu ficha de Google y las reseñas",duration:"9 min",tipo:"P",ia:!1,summary:"La ficha de Google es lo que sale cuando alguien busca tu nombre o tu servicio en el mapa. La rellenas entera: qué haces, zona, horario, fotos y contacto. Y aprendes a pedir reseñas a quien ya ha trabajado contigo y a contestarlas.",keyTakeaways:["Sabrás crear y rellenar tu ficha de Google.","Sabrás pedir una reseña de forma sencilla.","Sabrás contestar las reseñas, también las malas."],video:null},{id:"m9_l2",title:"9.2 Aparecer cuando buscan lo que vendes en tu ciudad",duration:"8 min",tipo:"C+P",ia:!1,summary:"La gente busca cosas como «fotógrafo de bodas en Zaragoza». Entiendes cómo decide Google a quién enseña y qué puedes hacer tú para aparecer. Ves en pantalla dónde poner tu servicio y tu ciudad en tu web y en tu ficha.",keyTakeaways:["Sabrás qué escribe tu cliente cuando busca lo que vendes.","Sabrás poner tu servicio y tu ciudad en los sitios que importan.","Sabrás comprobar si apareces al buscarte."],video:null},{id:"m9_l3",title:"9.3 Escribir contenido con IA que Google enseña",duration:"9 min",tipo:"P",ia:!0,summary:"Escribes con Claude una página que responde a una pregunta real de tu cliente. Le das la pregunta, lo que tú sabes del tema y un ejemplo tuyo. Después lo revisas y añades tu experiencia, porque un texto copiado tal cual de la IA no le sirve a nadie.",keyTakeaways:["Sabrás elegir una pregunta que de verdad se hace tu cliente.","Sabrás escribir con Claude una respuesta clara y útil.","Sabrás añadir tus ejemplos para que el texto sea tuyo."],video:null},{id:"m9_l4",title:"9.4 Que te recomienden también las IA (ChatGPT, Gemini, Claude)",duration:"8 min",tipo:"C+P",ia:!1,summary:"Cada vez más gente pregunta a una IA en vez de buscar en Google. No hay un truco que lo asegure, pero sí cosas que ayudan: que tu información esté clara, que diga lo mismo en todos los sitios y que haya reseñas. Compruebas en pantalla qué dicen hoy las IA de tu negocio.",keyTakeaways:["Sabrás preguntar a una IA por tu negocio para ver qué dice.","Sabrás dejar tu información clara e igual en todos los sitios.","Sabrás qué tipo de contenido ayuda a que te nombren."],video:null}]},{id:"m10",ruta:"b3",number:"Módulo 10",icon:"ri-money-euro-circle-line",title:"Antes de gastar un euro",description:"Sabes si ya te toca meter dinero en anuncios o todavía no. Y sales con la cuenta hecha: cuánto puedes pagar por un cliente, qué tiene que estar medido y con cuánto empezar.",disponible:"2026-11-30",lessons:[{id:"m10_l1",title:"10.1 Cuándo meter dinero (y cuándo todavía no)",duration:"7 min",tipo:"C",ia:!1,summary:"Los anuncios no arreglan una oferta que nadie quiere: solo hacen que la vea más gente. Aquí repasas tres señales que te dicen si ya te toca pagar por llegar a más empresas o si antes tienes que seguir contactando gratis.",keyTakeaways:["Saber qué tres cosas tienes que tener antes de pagar anuncios.","Distinguir si te falla la oferta o si solo te falta que te vea más gente.","Decidir hoy si te toca este bloque o seguir en el anterior."],video:null},{id:"m10_l2",title:"10.2 Cuánto te puede costar un cliente: la cuenta sencilla",duration:"9 min",tipo:"C+P",ia:!1,summary:"Haces la cuenta en una hoja de cálculo con tus propios números: lo que te deja un cliente, cuántos contactos necesitas para una reunión y cuántas reuniones para una venta. Sales con una cifra: lo máximo que puedes pagar por cada contacto sin perder dinero.",keyTakeaways:["Calcular cuánto te deja de verdad un cliente.","Sacar lo máximo que puedes pagar por un contacto.","Saber cuándo un anuncio te sale caro y hay que pararlo."],video:null},{id:"m10_l3",title:"10.3 Medir bien: lo que tiene que estar instalado antes de empezar",duration:"8 min",tipo:"P",ia:!1,summary:"Antes de pagar un anuncio, tu web tiene que contarte qué pasa en ella. Dejas puesto el contador de visitas, el aviso de cada formulario enviado y una página de gracias. Al final haces una prueba tú mismo para ver que todo se apunta.",keyTakeaways:["Poner un contador de visitas en tu web.","Hacer que cada formulario enviado quede apuntado.","Comprobar con una prueba tuya que la medición funciona."],video:null},{id:"m10_l4",title:"10.4 Con cuánto empezar y cómo repartirlo",duration:"7 min",tipo:"C",ia:!1,summary:"El primer dinero en anuncios es para aprender, no para ganar. Decides una cantidad que puedas perder sin agobiarte, la pones en un solo canal y la repartes por días para tener tiempo de ver qué funciona.",keyTakeaways:["Fijar un presupuesto de prueba que no te quite el sueño.","Elegir un solo canal para empezar.","Repartir el dinero por días y poner una fecha para revisar."],video:null}]},{id:"m11",ruta:"b3",number:"Módulo 11",icon:"ri-mail-send-line",title:"Campañas de email a muchas empresas",description:"Aprendes a escribir a cientos de empresas sin que tu correo acabe en spam. Preparas los buzones de envío, escribes la campaña con Claude y conviertes las respuestas en reuniones.",disponible:"2026-12-07",lessons:[{id:"m11_l1",title:"11.1 Cuándo tiene sentido enviar a cientos",duration:"7 min",tipo:"C",ia:!1,summary:"Enviar a cientos solo tiene sentido cuando un mensaje ya te ha dado respuestas escribiendo uno a uno. Aquí ves cuándo dar el salto, qué necesitas tener listo y qué puedes esperar de una campaña así.",keyTakeaways:["Saber cuándo pasar de escribir uno a uno a enviar a muchos.","Comprobar que tu mensaje ya funciona en pequeño.","Tener claro lo que necesitas: lista, buzones de envío y un mensaje probado."],video:null},{id:"m11_l2",title:"11.2 Dominios de envío y calentamiento, explicado fácil",duration:"9 min",tipo:"C+P",ia:!1,summary:"Si envías cientos de correos desde tu dirección de siempre, todo tu correo puede acabar en spam. Por eso se usa una dirección aparte, solo para campañas, y se empieza poco a poco, como quien empieza en el gimnasio. Ves cómo se compra y cómo se prepara.",keyTakeaways:["Entender por qué no se envía desde tu correo principal.","Comprar una dirección aparte para campañas y crear sus buzones.","Calentar un buzón: empezar con pocos correos al día e ir subiendo."],video:null},{id:"m11_l3",title:"11.3 Configurar la herramienta de envío",duration:"10 min",tipo:"P",ia:!1,summary:"Conectas tus buzones a una herramienta de envío y subes tu lista de empresas en un archivo. Ese archivo lo sacas del Organizador de llamadas con el botón «Exportar CSV». Dejas puesto el límite de correos al día, el horario y la espera entre un correo y el siguiente.",keyTakeaways:["Conectar tus buzones a la herramienta de envío.","Subir tu lista de empresas con su email en un archivo.","Poner un límite de correos al día y horario de oficina."],video:null},{id:"m11_l4",title:"11.4 Escribir la campaña con Claude",duration:"9 min",tipo:"P",ia:!0,summary:"Le das a Claude tu oferta, tu tipo de cliente y un correo que ya te haya funcionado. Te devuelve la campaña entera: tres correos cortos y varios asuntos para probar. Tú la revisas y la dejas con tu forma de hablar.",keyTakeaways:["Pedirle a Claude una campaña de tres correos con la instrucción ya escrita.","Usar huecos como el nombre o la ciudad para que cada correo suene escrito a mano.","Revisar y corregir lo que escribe la IA antes de enviar nada."],video:null},{id:"m11_l5",title:"11.5 No caer en spam",duration:"8 min",tipo:"P",ia:!1,summary:"Repasas lo que manda un correo a spam: listas con direcciones que no existen, enlaces de más, palabras de anuncio y envíos de golpe. Limpias tu lista, haces un envío de prueba y dejas una forma fácil de darse de baja.",keyTakeaways:["Limpiar tu lista de correos que no existen.","Escribir correos sin enlaces de más ni palabras de anuncio.","Hacer un envío de prueba y mirar a qué bandeja llega."],video:null},{id:"m11_l6",title:"11.6 Gestionar las respuestas y pasarlas a reunión",duration:"8 min",tipo:"P",ia:!1,summary:"Cada respuesta es de un tipo: le interesa, ahora no, no es la persona o no quiere más correos. Ves qué contestar a cada una y cómo mover la ficha de esa empresa en el Organizador de llamadas para que no se pierda.",keyTakeaways:["Clasificar cada respuesta en uno de cuatro tipos.","Contestar en pocas líneas proponiendo día y hora.","Mover la ficha a «Reunión agendada» en el Organizador de llamadas."],video:null}]},{id:"m12",ruta:"b3",number:"Módulo 12",icon:"ri-facebook-circle-line",title:"Anuncios en Meta (Facebook e Instagram)",description:"Montas tu primera campaña en Facebook e Instagram para que personas interesadas te dejen su contacto. Y aprendes a leer los resultados para saber qué tocar y qué dejar quieto.",disponible:"2026-12-14",lessons:[{id:"m12_l1",title:"12.1 Cómo funciona Meta, sin tecnicismos",duration:"7 min",tipo:"C",ia:!1,summary:"Meta enseña tu anuncio a la gente que más se parece a quien ya te hace caso. Es como repartir folletos, pero eligiendo a quién se lo das. Entiendes qué pagas, qué decide Meta y qué decides tú.",keyTakeaways:["Explicar con tus palabras cómo decide Meta a quién enseña tu anuncio.","Saber las tres cosas que eliges tú: objetivo, público y anuncio.","Entender por qué los primeros días son de prueba."],video:null},{id:"m12_l2",title:"12.2 Preparar la cuenta paso a paso",duration:"9 min",tipo:"P",ia:!1,summary:"Creas lo que hace falta para anunciarte: la página de tu negocio, la cuenta de anuncios y la forma de pago. También dejas puesto en tu web el código de Meta, que es lo que le avisa cuando alguien te deja su contacto.",keyTakeaways:["Crear tu cuenta de anuncios y unirla a tu página.","Poner tu forma de pago y un límite de gasto.","Instalar en tu web el código de Meta y comprobar que funciona."],video:null},{id:"m12_l3",title:"12.3 Tu primera campaña para conseguir contactos",duration:"10 min",tipo:"P",ia:!1,summary:"Creas la campaña de principio a fin con el objetivo de conseguir contactos. Eliges entre un formulario dentro de Meta o llevar a la gente a tu página, pones el presupuesto del día y la dejas lista para revisar.",keyTakeaways:["Crear una campaña con el objetivo de conseguir contactos.","Elegir entre el formulario de Meta y tu propia página.","Poner un presupuesto diario y una fecha de fin."],video:null},{id:"m12_l4",title:"12.4 A quién enseñarle el anuncio",duration:"8 min",tipo:"P",ia:!1,summary:"Decides quién ve tu anuncio: zona, edad y poco más. Ves por qué al empezar conviene no recortar demasiado, y cómo usar las visitas de tu web o tu lista de clientes cuando ya las tengas.",keyTakeaways:["Elegir zona y edad sin recortar de más.","Saber cuándo usar intereses y cuándo dejarlo abierto.","Crear un público con la gente que ya visitó tu web."],video:null},{id:"m12_l5",title:"12.5 Anuncios que funcionan: imagen, vídeo y texto con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Con Claude sacas varias formas de contar tu oferta. Después escribes el texto del anuncio, la idea de la imagen y el guion de un vídeo corto. Preparas tres anuncios distintos para que sean los resultados los que te digan cuál gusta más.",keyTakeaways:["Pedirle a Claude cinco formas distintas de contar tu oferta.","Escribir el texto del anuncio y el guion de un vídeo de 30 segundos.","Preparar tres anuncios distintos para compararlos."],video:null},{id:"m12_l6",title:"12.6 Leer los resultados: qué mirar y qué ignorar",duration:"8 min",tipo:"P",ia:!1,summary:"El panel de Meta tiene decenas de números y solo necesitas cuatro. Aprendes a mirar cuánto has gastado, cuántos contactos han entrado, cuánto cuesta cada uno y cuántos acaban en reunión.",keyTakeaways:["Dejar a la vista solo las columnas que importan.","Calcular cuánto te cuesta cada contacto y cada reunión.","No decidir por los «me gusta» ni por las visualizaciones."],video:null},{id:"m12_l7",title:"12.7 Qué tocar cuando no funciona y cuándo subir el presupuesto",duration:"9 min",tipo:"C+P",ia:!1,summary:"Cuando un anuncio no funciona, el fallo está en uno de tres sitios: el anuncio, el público o la página. Ves cómo encontrar cuál es, cambiar una sola cosa cada vez y subir el presupuesto poco a poco cuando los números salen.",keyTakeaways:["Encontrar si falla el anuncio, el público o la página.","Cambiar una sola cosa cada vez para saber qué ha funcionado.","Subir el presupuesto poco a poco y solo con números buenos."],video:null}]},{id:"m13",ruta:"b3",number:"Módulo 13",icon:"ri-google-line",title:"Anuncios en Google",description:"Pones tu anuncio delante de quien ya está buscando lo que vendes. Sales con una campaña de búsqueda montada, sus palabras elegidas y los fallos caros evitados.",disponible:"2026-12-21",lessons:[{id:"m13_l1",title:"13.1 Cuándo Google y cuándo Meta",duration:"7 min",tipo:"C",ia:!1,summary:"En Google la gente busca. En Meta la gente pasa el rato. Con esa diferencia decides dónde poner tu dinero, según lo que vendes y según si tu cliente ya sabe que lo necesita.",keyTakeaways:["Explicar la diferencia entre quien busca y quien pasa el rato.","Decidir si lo tuyo encaja mejor en Google, en Meta o en los dos.","Empezar por uno solo y no repartir el dinero."],video:null},{id:"m13_l2",title:"13.2 Campaña de búsqueda: aparecer cuando te buscan",duration:"10 min",tipo:"P",ia:!1,summary:"Creas una campaña de búsqueda paso a paso: tu anuncio sale cuando alguien escribe en Google lo que tú vendes. Eliges la zona, el presupuesto del día y la página a la que llega quien hace clic.",keyTakeaways:["Crear una campaña de búsqueda desde cero.","Elegir zona, horario y presupuesto diario.","Mandar cada anuncio a la página que habla de eso mismo."],video:null},{id:"m13_l3",title:"13.3 Palabras y anuncios con Claude",duration:"9 min",tipo:"P",ia:!0,summary:"Claude te ayuda a sacar las búsquedas que haría tu cliente y las búsquedas por las que no quieres pagar. Con esa lista escribes varios títulos y descripciones de anuncio, y los revisas antes de subirlos.",keyTakeaways:["Sacar con Claude las palabras por las que quieres aparecer.","Hacer la lista de palabras por las que no quieres pagar.","Escribir títulos y descripciones que caben en el espacio que da Google."],video:null},{id:"m13_l4",title:"13.4 Volver a salirle a quien ya te visitó",duration:"8 min",tipo:"P",ia:!1,summary:"Casi nadie te deja su contacto la primera vez que entra en tu web. Montas una campaña que le vuelve a enseñar tu anuncio a quien ya te visitó, con un límite para no resultar pesado.",keyTakeaways:["Crear una lista con la gente que ya visitó tu web.","Montar un anuncio de recuerdo solo para esa lista.","Limitar cuántas veces lo ve la misma persona."],video:null},{id:"m13_l5",title:"13.5 Los errores que más dinero cuestan",duration:"7 min",tipo:"C",ia:!1,summary:"Repasas los fallos que más dinero queman en Google: palabras demasiado abiertas, no mirar qué buscó la gente, mandar a la portada de la web y no medir. Te llevas una lista para revisar tu campaña cada semana.",keyTakeaways:["Reconocer los fallos que más dinero hacen perder.","Revisar cada semana qué buscó la gente que hizo clic.","Parar a tiempo lo que gasta y no trae contactos."],video:null}]},{id:"m14",ruta:"b3",number:"Módulo 14",icon:"ri-layout-4-line",title:"Páginas y embudos",description:"Un embudo es el camino que hace alguien desde que te ve por primera vez hasta que te paga. Aquí montas el tuyo: una página con un solo objetivo, algo que regalar a cambio del contacto y los correos que salen solos después.",disponible:"2027-01-11",lessons:[{id:"m14_l1",title:"14.1 Una página, un objetivo",duration:"7 min",tipo:"C",ia:!1,summary:"Una página que pide cinco cosas no consigue ninguna. Ves las partes de una página que solo busca una acción y por qué la portada de tu web no sirve para recibir a quien llega de un anuncio.",keyTakeaways:["Elegir la única acción que pides en la página.","Ordenar la página: promesa, prueba, cómo funciona y botón.","Quitar menús y enlaces que distraen."],video:null},{id:"m14_l2",title:"14.2 La página para reservar reunión, hecha con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Claude escribe contigo el texto de la página y te la da hecha, con tu oferta y un botón para reservar hora en tu calendario. La publicas y haces una reserva de prueba para ver que todo llega.",keyTakeaways:["Pedirle a Claude el texto y la página con la instrucción ya escrita.","Enlazar tu calendario para que reserven hora solos.","Hacer una reserva de prueba antes de enseñarla a nadie."],video:null},{id:"m14_l3",title:"14.3 Regalar algo a cambio del contacto",duration:"8 min",tipo:"C+P",ia:!1,summary:"Mucha gente no está lista para reunirse, pero sí para llevarse algo útil. Eliges un regalo sencillo, como una lista, una plantilla o una revisión gratis. Después montas la página donde lo piden dejando su contacto.",keyTakeaways:["Elegir un regalo que resuelva un problema pequeño de tu cliente.","Prepararlo en una tarde, sin diseño complicado.","Montar la página donde lo piden a cambio de su contacto."],video:null},{id:"m14_l4",title:"14.4 Vídeo de venta y clases en directo para captar",duration:"8 min",tipo:"C",ia:!1,summary:"Un vídeo de venta explica tu oferta por ti a cualquier hora. Una clase en directo te deja enseñar y contestar dudas a muchos a la vez. Ves cuándo usar cada uno y qué partes tiene que tener.",keyTakeaways:["Saber cuándo conviene un vídeo y cuándo una clase en directo.","Seguir el orden de un vídeo de venta: problema, solución, prueba y siguiente paso.","Terminar siempre con una sola invitación clara."],video:null},{id:"m14_l5",title:"14.5 Los correos automáticos que siguen al contacto",duration:"9 min",tipo:"P",ia:!1,summary:"Quien te deja su contacto y no recibe nada se olvida de ti enseguida. Montas una serie corta de correos que salen solos: la entrega de lo prometido, una ayuda, un caso y la invitación a reunirse.",keyTakeaways:["Escribir cuatro correos cortos que se envían solos.","Programar cuántos días pasan entre uno y otro.","Parar la serie cuando la persona reserva reunión."],video:null},{id:"m14_l6",title:"14.6 Probar y mejorar: qué cambiar primero",duration:"8 min",tipo:"P",ia:!1,summary:"Tu página tiene un número que manda: de cada cien visitas, cuántas dejan su contacto. Aprendes a mirarlo y a probar los cambios en orden: primero el titular, luego la oferta y después el botón.",keyTakeaways:["Calcular cuántas visitas de cada cien dejan su contacto.","Saber qué cambiar primero y qué dejar para luego.","Probar un cambio cada vez y esperar a tener visitas suficientes."],video:null}]},{id:"m15",ruta:"b4",number:"Módulo 15",icon:"ri-shake-hands-line",title:"De la reunión al sí",description:"Llevas una reunión desde el primer saludo hasta el pago. Preparas, preguntas, presentas tu propuesta, respondes a las dudas y cierras con un contrato sencillo.",disponible:"2026-11-02",lessons:[{id:"m15_l1",title:"15.1 Prepara la reunión en 15 minutos con Claude",duration:"8 min",tipo:"P",ia:!0,summary:"Le pasas a Claude los datos de la empresa: su web, sus reseñas y lo que hablasteis por teléfono. Te devuelve un resumen del negocio, sus posibles problemas y las preguntas que te conviene hacer. Tú compruebas que lo que dice es verdad.",keyTakeaways:["Reunir en cinco minutos los datos de la empresa.","Pedirle a Claude el resumen y las preguntas con la instrucción ya escrita.","Llegar a la reunión con una hoja de una página."],video:null},{id:"m15_l2",title:"15.2 La primera reunión: preguntas, no discurso",duration:"9 min",tipo:"C",ia:!1,summary:"La primera reunión no es para presentar nada: es para entender. Ves el orden de las preguntas, cómo escuchar sin interrumpir y cómo terminar quedando para una segunda reunión con fecha.",keyTakeaways:["Abrir la reunión explicando cómo va a ir.","Hacer preguntas que saquen el problema y lo que les cuesta.","Salir con la fecha de la siguiente reunión puesta."],video:null},{id:"m15_l3",title:"15.3 Propuesta, no presupuesto",duration:"7 min",tipo:"C",ia:!1,summary:"Un presupuesto es una lista de precios. Una propuesta cuenta el problema del cliente, cómo lo vas a resolver y qué va a cambiar. Ves las partes de una propuesta de dos páginas y por qué se presenta hablando.",keyTakeaways:["Distinguir un presupuesto de una propuesta.","Ordenar la propuesta: su problema, tu solución, plazos y precio.","Presentarla hablando en vez de mandarla por correo y esperar."],video:null},{id:"m15_l4",title:"15.4 Escribe la propuesta con Claude a partir de tus notas",duration:"9 min",tipo:"P",ia:!0,summary:"Pegas en Claude tus notas de la reunión, tal como las apuntaste. Te devuelve la propuesta ordenada y con las palabras que usó el cliente. Tú revisas cifras, plazos y precio antes de enseñarla.",keyTakeaways:["Tomar notas de la reunión que luego sirvan.","Convertir esas notas en propuesta con una sola instrucción.","Revisar precio, plazos y promesas antes de enviarla."],video:null},{id:"m15_l5",title:"15.5 La segunda reunión, paso a paso",duration:"8 min",tipo:"C",ia:!1,summary:"En la segunda reunión repasas lo que te contaron, presentas la propuesta y pides una decisión. Ves el orden minuto a minuto y la frase para preguntar si seguís adelante sin sonar agresivo.",keyTakeaways:["Empezar repasando su problema con sus propias palabras.","Presentar la propuesta en diez minutos.","Pedir la decisión con una pregunta sencilla y esperar callado."],video:null},{id:"m15_l6",title:'15.6 "Es caro", "me lo pienso", "lo consulto": qué responder',duration:"9 min",tipo:"C",ia:!1,summary:"Casi todos los «no» son dudas sin resolver. Ves qué hay detrás de cada una de estas tres frases y una respuesta tranquila para cada caso, dicha entera y con ejemplos.",keyTakeaways:["Averiguar qué duda hay detrás de «es caro».","Poner fecha a un «me lo pienso».","Ayudar al cliente a explicárselo a la persona con la que lo consulta."],video:null},{id:"m15_l7",title:"15.7 Cerrar y cobrar: contrato sencillo y enlace de pago",duration:"8 min",tipo:"P",ia:!1,summary:"Cuando te dicen que sí, tu trabajo es ponerlo fácil. Preparas un contrato de una página, envías un enlace de pago y apuntas la venta con su importe en el Organizador de llamadas.",keyTakeaways:["Preparar un contrato sencillo de una página.","Enviar un enlace de pago el mismo día del sí.","Pasar la ficha a «Venta cerrada» y apuntar el importe."],video:null}]},{id:"m16",ruta:"b5",number:"Módulo 16",icon:"ri-heart-3-line",title:"Que el cliente se quede y te recomiende",description:"Un cliente contento se queda, te compra más y te trae a otros. Aquí aprendes a empezar bien, a enseñar tu trabajo cada mes y a pedir recomendaciones sin cortarte.",disponible:"2027-01-18",lessons:[{id:"m16_l1",title:"16.1 La primera semana con tu cliente",duration:"7 min",tipo:"C",ia:!1,summary:"La primera semana marca cómo va a ser toda la relación. Ves qué enviar el primer día, qué pedirle al cliente y cómo darle un primer resultado pequeño cuanto antes.",keyTakeaways:["Enviar un mensaje de bienvenida con los pasos y las fechas.","Pedir de una vez todo lo que necesitas del cliente.","Dar un primer resultado pequeño en la primera semana."],video:null},{id:"m16_l2",title:"16.2 La reunión de seguimiento que evita sustos",duration:"7 min",tipo:"C",ia:!1,summary:"Una reunión corta cada cierto tiempo evita que los problemas te pillen por sorpresa. Ves cada cuánto hacerla, el orden de los temas y cómo dar una mala noticia a tiempo.",keyTakeaways:["Fijar una reunión de seguimiento con día y hora fijos.","Seguir siempre el mismo orden: lo hecho, los resultados y el siguiente paso.","Contar los problemas antes de que el cliente los descubra."],video:null},{id:"m16_l3",title:"16.3 El informe mensual hecho con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Le das a Claude los números del mes y lo que has hecho. Te devuelve un informe de una página que cualquier dueño de negocio entiende. Tú compruebas los números uno a uno antes de enviarlo.",keyTakeaways:["Reunir los números del mes en diez minutos.","Convertirlos en un informe claro con una sola instrucción.","Explicar qué significa cada número para el negocio del cliente."],video:null},{id:"m16_l4",title:"16.4 Por qué se van los clientes (y cómo verlo venir)",duration:"8 min",tipo:"C",ia:!1,summary:"Un cliente casi nunca se va de golpe: avisa antes sin decirlo. Ves las señales, como contestar tarde, preguntar menos o poner pegas a la factura. Y qué hacer cuando aparece la primera.",keyTakeaways:["Reconocer las señales de que un cliente se está enfriando.","Llamar en cuanto aparece la primera señal.","Preguntar a tiempo qué esperaba y qué no está viendo."],video:null},{id:"m16_l5",title:"16.5 Venderle algo más sin presionar",duration:"7 min",tipo:"C",ia:!1,summary:"Venderle algo más a un cliente contento es ayudarle con su siguiente problema. Ves cuándo proponerlo, cómo decirlo y por qué solo se hace después de un buen resultado.",keyTakeaways:["Detectar el siguiente problema de tu cliente.","Elegir el momento: justo después de un buen resultado.","Proponerlo como una idea, sin presión y con el precio claro."],video:null},{id:"m16_l6",title:"16.6 Pedir recomendaciones y testimonios",duration:"7 min",tipo:"C",ia:!1,summary:"Las recomendaciones no llegan solas: se piden. Ves el momento bueno para pedirlas, la frase exacta y cómo conseguir un testimonio aunque al cliente no le guste escribir.",keyTakeaways:["Pedir una recomendación con una frase concreta.","Conseguir un testimonio con tres preguntas sencillas.","Usar ese testimonio en tu web y en tus mensajes, con su permiso."],video:null}]},{id:"m17",ruta:"b6",number:"Módulo 17",icon:"ri-bar-chart-box-line",title:"Tus números y tu sistema",description:"Dejas de trabajar a ojo. Miras cinco números cada semana, encuentras en qué paso pierdes clientes y montas una rutina que funciona aunque tengas un mal día.",disponible:"2027-01-25",lessons:[{id:"m17_l1",title:"17.1 Los cinco números que miras cada viernes",duration:"8 min",tipo:"C+P",ia:!1,summary:"Cinco números te dicen cómo ha ido tu semana: empresas contactadas, reuniones, ventas, dinero vendido y cuántas te han dicho que no. Ves dónde salen en el Organizador de llamadas y cómo apuntarlos cada viernes.",keyTakeaways:["Encontrar tus cinco números arriba del Organizador de llamadas.","Apuntarlos cada viernes en la misma hoja.","Comparar una semana con la anterior en cinco minutos."],video:null},{id:"m17_l2",title:"17.2 Dónde se te escapan los clientes",duration:"8 min",tipo:"C",ia:!1,summary:"Entre el primer contacto y la venta hay varios pasos, y en uno se te cae más gente que en los demás. Con tus números encuentras cuál es y decides qué módulo de la Academia repasar.",keyTakeaways:["Dibujar tus pasos: contacto, respuesta, reunión y venta.","Ver en qué paso pierdes más gente.","Arreglar primero ese paso y dejar los demás quietos."],video:null},{id:"m17_l3",title:"17.3 Automatiza lo repetitivo con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Haces la lista de lo que repites cada semana: resúmenes, correos de seguimiento, informes. Preparas con Claude una instrucción guardada para cada tarea, para hacerla en minutos. La IA escribe; tú revisas y envías.",keyTakeaways:["Hacer la lista de tus tareas que se repiten.","Guardar en tu Proyecto de Claude una instrucción para cada una.","Revisar siempre lo que escribe la IA antes de usarlo."],video:null},{id:"m17_l4",title:"17.4 Tu organizador al día: que no se pierda ningún contacto",duration:"8 min",tipo:"P",ia:!1,summary:"Repasas el Organizador de llamadas columna por columna para que ninguna empresa se quede olvidada. Mueves cada ficha a su etapa, apuntas el importe de cada venta y descargas una copia con «Exportar CSV».",keyTakeaways:["Mover cada ficha a su etapa arrastrándola o con el desplegable.","Apartar en «No interesado» a quien no quiere, sin borrarlo.","Descargar una copia de tu tablero con «Exportar CSV»."],video:null},{id:"m17_l5",title:"17.5 Tu semana tipo",duration:"7 min",tipo:"C",ia:!1,summary:"Una buena semana no se improvisa: se repite. Montas tu semana tipo con bloques fijos para contactar, para las reuniones, para entregar el trabajo y para mirar tus números.",keyTakeaways:["Reservar cada día un bloque fijo para contactar empresas.","Agrupar las reuniones en días concretos.","Cerrar la semana el viernes con tus cinco números."],video:null}]},{id:"m18",ruta:"b6",number:"Módulo 18",icon:"ri-team-line",title:"Equipo y agencia",description:"Cuando ya no llegas a todo, toca dejar de hacerlo todo tú. Aprendes qué soltar primero, cómo encontrar a alguien de confianza y cómo enseñarle a trabajar como tú.",disponible:"2027-02-01",lessons:[{id:"m18_l1",title:"18.1 Cuándo contratar y qué soltar primero",duration:"7 min",tipo:"C",ia:!1,summary:"Contratar pronto te quita dinero. Contratar tarde te quita clientes. Ves las señales de que ya toca y cuál es la primera tarea que conviene soltar: la que se repite y no necesita tu cabeza.",keyTakeaways:["Reconocer las señales de que ya no llegas a todo.","Elegir la primera tarea que vas a soltar.","Hacer la cuenta de si te lo puedes permitir antes de dar el paso."],video:null},{id:"m18_l2",title:"18.2 Dónde encontrar gente y cómo elegir",duration:"8 min",tipo:"P",ia:!1,summary:"Ves dónde buscar colaboradores por horas o por proyecto y cómo escribir un anuncio claro. Y cómo elegir bien: con una prueba pequeña y pagada, no solo con una entrevista.",keyTakeaways:["Escribir un anuncio que explique la tarea y lo que pagas.","Buscar colaboradores en LinkedIn y en páginas de profesionales autónomos.","Elegir con una prueba pequeña y pagada."],video:null},{id:"m18_l3",title:"18.3 Enseñar a alguien tu forma de trabajar, con ayuda de la IA",duration:"9 min",tipo:"P",ia:!0,summary:"Te grabas haciendo una tarea y explicándola en voz alta. Le pegas a Claude el texto de lo que has dicho y te lo convierte en una guía paso a paso, con su lista para comprobar. Así la otra persona aprende sin que se lo expliques tres veces.",keyTakeaways:["Grabarte haciendo una tarea mientras la explicas.","Convertir esa explicación en una guía paso a paso con Claude.","Comprobar que otra persona puede seguirla sin preguntarte."],video:null},{id:"m18_l4",title:"18.4 De trabajar solo a agencia pequeña",duration:"8 min",tipo:"C",ia:!1,summary:"Pasar de trabajar solo a tener una agencia pequeña cambia tu trabajo: menos hacer y más organizar. Ves los papeles que hay que cubrir, cómo repartirlos y qué no soltar todavía.",keyTakeaways:["Separar los tres papeles: vender, entregar y organizar.","Decidir con cuál te quedas tú al principio.","Mantener la calidad con revisiones cortas y fijas."],video:null},{id:"m18_l5",title:"18.5 Lo siguiente: qué mejorar cuando ya funciona",duration:"7 min",tipo:"C",ia:!1,summary:"Cuando el sistema ya funciona, la tentación es cambiarlo todo. Ves cómo elegir una sola mejora cada vez, ya sea subir precios, buscar mejores clientes o abrir un canal nuevo. Y cómo seguir usando la Academia y la comunidad.",keyTakeaways:["Elegir una sola mejora para los próximos tres meses.","Saber cuándo subir precios y cuándo buscar clientes más grandes.","Volver al módulo que toque cuando un número baje."],video:null}]},{id:"s1",ruta:"bx",number:"Servicio 1",icon:"ri-google-line",title:"Reseñas y ficha de Google para negocios locales",description:"El servicio más fácil para empezar. Aprendes a poner al día la ficha de Google de un negocio y a llevar sus reseñas, a venderlo y a entregarlo cada mes.",disponible:"2026-10-26",lessons:[{id:"s1_l1",title:"S1.1 Qué es llevar la ficha de Google y las reseñas de un negocio, y cuáles lo necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué es la ficha de Google: lo que sale cuando alguien busca un negocio en Google o en el mapa. Ves qué trabajo haces tú ahí y por qué a una clínica dental, a un taller o a una peluquería les ayuda a que les llamen más. Terminas sabiendo a qué negocios ofrecérselo primero.",keyTakeaways:["Explicar qué es la ficha de Google con palabras normales.","Reconocer en un minuto una ficha descuidada.","Elegir los tipos de negocio que más lo necesitan."],video:null},{id:"s1_l2",title:"S1.2 Contestar reseñas y poner al día una ficha de Google con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Coges la ficha de un negocio de ejemplo y la revisas punto por punto con Claude: horario, fotos, servicios y descripción. Después escribes con Claude las respuestas a las reseñas, las buenas y las malas, y las repasas antes de publicarlas. Te llevas la lista de revisión y las instrucciones para copiar y pegar.",keyTakeaways:["Revisar una ficha con una lista de puntos fija.","Contestar reseñas buenas y malas con Claude, leyéndolas siempre antes de publicar.","Preparar el mensaje con el que el negocio pide reseñas a sus clientes de verdad."],video:null},{id:"s1_l3",title:"S1.3 Vender la ficha y las reseñas de Google: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Ves a quién llamar primero: negocios con pocas reseñas, con valoración baja o con reseñas sin contestar. Escuchas una llamada de ejemplo entera. Y aprendes a poner el precio: un trabajo inicial para dejar la ficha bien y una cuota al mes por mantenerla, sin prometer estrellas ni puestos en Google.",keyTakeaways:["Encontrar negocios con la ficha floja en el Buscador de empresas.","Explicar el servicio en dos frases que un dueño entiende.","Poner un precio de arranque y una cuota mensual sin regalar tu trabajo."],video:null},{id:"s1_l4",title:"S1.4 El repaso mensual de reseñas y ficha de cada cliente, con IA y sin que te coma el tiempo",duration:"8 min",tipo:"P",ia:!0,summary:"Montas una rutina fija para cada cliente: contestar las reseñas nuevas, subir fotos y publicar una novedad. Claude te prepara los borradores y el informe del mes con lo que ha cambiado. Así todos los clientes se hacen igual y ninguno se te alarga.",keyTakeaways:["Seguir la misma lista de tareas con todos tus clientes.","Hacer con Claude los borradores de respuestas y novedades del mes.","Enviar un informe mensual corto que el dueño entiende a la primera."],video:null}]},{id:"s2",ruta:"bx",number:"Servicio 2",icon:"ri-global-line",title:"Webs sencillas para negocios que no tienen",description:"Aprendes a hacer una web clara de una página para un negocio que no tiene ninguna, a vendérsela y a mantenerla al día sin que te quite horas.",disponible:"2026-10-26",lessons:[{id:"s2_l1",title:"S2.1 Qué es una web sencilla de una página y qué negocios la necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué lleva una web sencilla: qué hace el negocio, dónde está, fotos, opiniones y un botón para llamar o pedir cita. Ves por qué un negocio sin web pierde a la gente que lo busca antes de ir. Y qué negocios suelen estar sin ella: reformas, talleres, peluquerías o restaurantes pequeños.",keyTakeaways:["Decir qué partes tiene una web sencilla que funciona.","Explicar a un dueño qué pierde por no tener web.","Saber qué tipos de negocio suelen estar sin web."],video:null},{id:"s2_l2",title:"S2.2 Hacer la web de una página de un negocio con IA, paso a paso",duration:"10 min",tipo:"P",ia:!0,summary:"Haces la web de un negocio de ejemplo de principio a fin. Le das a Claude los datos del negocio y te devuelve los textos y la página montada. Tú la revisas, cambias lo que no sea verdad y la dejas lista para enseñársela al cliente.",keyTakeaways:["Reunir los datos del negocio con una lista de preguntas.","Pedir a Claude los textos y la página con una instrucción completa.","Revisar la web en el móvil antes de enseñarla."],video:null},{id:"s2_l3",title:"S2.3 Vender una web sencilla: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Buscas negocios con la etiqueta «Sin web» y aprendes qué decirles sin hablar de tecnología. Escuchas una llamada de ejemplo completa. Y ves cómo poner el precio: un pago por hacerla y una cuota pequeña al mes por tenerla al día.",keyTakeaways:["Sacar una lista de negocios sin web en tu ciudad.","Ofrecer la web hablando de clientes, no de páginas.","Separar el precio de hacerla del precio de mantenerla."],video:null},{id:"s2_l4",title:"S2.4 Mantener al día las webs de tus clientes cada mes con IA",duration:"8 min",tipo:"P",ia:!0,summary:"Organizas los cambios que piden los clientes para hacerlos todos juntos un día fijo. Claude te ayuda a cambiar textos, precios y horarios, y a comprobar que todo sigue funcionando. Te llevas la lista de revisión mensual y el mensaje con el que avisas al cliente de que ya está hecho.",keyTakeaways:["Recoger los cambios de cada cliente en un solo sitio.","Hacer con Claude los cambios de texto y comprobar que no se rompe nada.","Dejar claro qué cambios entran en la cuota y cuáles se cobran aparte."],video:null}]},{id:"s3",ruta:"bx",number:"Servicio 3",icon:"ri-instagram-line",title:"Redes sociales para negocios locales",description:"Aprendes a llevar las redes de un negocio de barrio: qué publicar, cómo prepararlo en una tanda con IA, cómo venderlo y cómo entregarlo cada mes con orden.",disponible:null,lessons:[{id:"s3_l1",title:"S3.1 Qué es llevar las redes sociales de un negocio local y cuáles lo necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué es llevar las redes de un negocio: publicar con constancia, contestar a quien escribe y enseñar el trabajo que hacen. Ves la diferencia entre una cuenta abandonada y una cuidada. Y a qué negocios les compensa más: los que venden por los ojos, como restaurantes, peluquerías, centros de estética o fotógrafos.",keyTakeaways:["Explicar qué incluye llevar las redes y qué no.","Detectar una cuenta abandonada con solo mirarla.","Elegir negocios a los que las redes sí les traen gente."],video:null},{id:"s3_l2",title:"S3.2 Preparar un mes de publicaciones para un negocio con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Con un negocio de ejemplo, le pides a Claude ideas para todo el mes y los textos de cada publicación. Las ordenas en un calendario y decides qué fotos o vídeos hacen falta. Revisas cada texto para que suene al negocio y no a robot.",keyTakeaways:["Sacar con Claude ideas de publicaciones para un mes entero.","Montar un calendario sencillo con día, texto y foto.","Corregir los textos para que suenen como habla el dueño."],video:null},{id:"s3_l3",title:"S3.3 Vender la gestión de redes sociales: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a ofrecerlo a negocios que llevan semanas sin publicar. Escuchas una conversación de ejemplo con el dueño de un restaurante. Y ves cómo poner el precio según lo que entregas: cuántas publicaciones al mes y quién hace las fotos, sin prometer seguidores ni ventas.",keyTakeaways:["Encontrar negocios con las redes paradas.","Decir qué vas a entregar cada mes con números claros.","Poner el precio por paquete de publicaciones, no por horas."],video:null},{id:"s3_l4",title:"S3.4 El calendario mensual de redes de cada cliente, hecho en una tanda con IA",duration:"8 min",tipo:"P",ia:!0,summary:"Montas un sistema para que cada cliente te lleve siempre lo mismo. Un día al mes pides las fotos, preparas todo con Claude y lo mandas a aprobar de una vez. Después lo dejas programado y solo queda contestar mensajes.",keyTakeaways:["Pedir al cliente fotos y novedades con un mensaje fijo.","Preparar con Claude todo el mes de un cliente en una sentada.","Conseguir que el cliente apruebe todo el mes de una vez."],video:null}]},{id:"s4",ruta:"bx",number:"Servicio 4",icon:"ri-play-circle-line",title:"Vídeos cortos para negocios",description:"Aprendes a hacer vídeos cortos para negocios, de la idea al vídeo montado, a venderlos como un paquete mensual y a grabar todo un mes en una sola visita.",disponible:null,lessons:[{id:"s4_l1",title:"S4.1 Qué son los vídeos cortos para negocios y cuáles los necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué es un vídeo corto: menos de un minuto, en vertical, para TikTok, Instagram y YouTube. Ves por qué a un negocio le sirve para que la gente de su zona lo conozca antes de entrar. Y qué negocios tienen más que enseñar: un taller, una clínica, un gimnasio o un restaurante.",keyTakeaways:["Explicar qué es un vídeo corto y dónde se publica.","Decir tres tipos de vídeo que puede grabar cualquier negocio.","Elegir negocios que tienen algo que enseñar cada semana."],video:null},{id:"s4_l2",title:"S4.2 De la idea al vídeo corto montado: guion, grabación y subtítulos con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Haces un vídeo de ejemplo entero. Claude te da ideas y te escribe un guion corto con su primera frase para enganchar. Después ves cómo grabarlo con el móvil y cómo montarlo con cortes y subtítulos.",keyTakeaways:["Pedir a Claude diez ideas y un guion de 40 segundos.","Grabar con el móvil con buena luz y buen sonido.","Montar el vídeo con cortes y subtítulos que se leen bien."],video:null},{id:"s4_l3",title:"S4.3 Vender vídeos cortos a un negocio: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a ofrecerlo enseñando un vídeo de muestra, que convence más que cualquier explicación. Escuchas qué decirle al dueño de un gimnasio. Y ves cómo poner el precio por paquete de vídeos al mes, contando quién graba y quién aparece, sin prometer visitas.",keyTakeaways:["Preparar un vídeo de muestra para enseñar en la reunión.","Explicar el servicio como un paquete de vídeos al mes.","Poner el precio según cuántos vídeos y quién los graba."],video:null},{id:"s4_l4",title:"S4.4 Un día de grabación al mes: entregar los vídeos de cada cliente con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Organizas el trabajo para grabar todos los vídeos del mes en una sola visita. Antes de ir, preparas con Claude los guiones y la lista de tomas. Después montas todos seguidos con la misma plantilla y los entregas con su texto para publicar.",keyTakeaways:["Preparar con Claude los guiones y la lista de tomas del mes.","Grabar todos los vídeos de un cliente en una visita.","Usar una plantilla de montaje para no empezar de cero."],video:null}]},{id:"s5",ruta:"bx",number:"Servicio 5",icon:"ri-whatsapp-line",title:"Citas por internet y WhatsApp que contesta solo",description:"Aprendes a montarle a un negocio una agenda para reservar cita por internet y los mensajes automáticos de WhatsApp, a venderlo y a revisarlo cada mes.",disponible:null,lessons:[{id:"s5_l1",title:"S5.1 Qué es reservar cita por internet y un WhatsApp que contesta solo, y qué negocios lo necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico las dos piezas: una agenda donde el cliente elige día y hora sin llamar, y unos mensajes de WhatsApp que responden al momento con lo básico. Ves cuántas citas se pierden cuando nadie coge el teléfono. Y qué negocios viven de la cita: peluquerías, clínicas, fisioterapeutas o talleres.",keyTakeaways:["Explicar qué es una agenda de citas por internet.","Decir qué puede contestar WhatsApp solo y qué no.","Reconocer negocios que pierden citas por no coger el teléfono."],video:null},{id:"s5_l2",title:"S5.2 Montar la agenda de citas y los mensajes automáticos de WhatsApp con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Montas la agenda de un negocio de ejemplo con sus servicios, duraciones y horarios. Con Claude escribes los mensajes de WhatsApp: el de bienvenida, el de fuera de horario y las respuestas a las preguntas de siempre. Lo pruebas todo como si fueras un cliente antes de darlo por bueno.",keyTakeaways:["Dar de alta servicios, horarios y huecos en una agenda de citas.","Escribir con Claude los mensajes automáticos de WhatsApp.","Probar el recorrido completo como lo haría un cliente."],video:null},{id:"s5_l3",title:"S5.3 Vender las citas por internet y el WhatsApp automático: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a ofrecerlo a negocios donde el dueño atiende y coge el teléfono a la vez. Escuchas qué decirle a una peluquería con un ejemplo completo. Y ves cómo poner el precio: un pago por dejarlo montado y una cuota al mes por revisarlo, contando aparte lo que cueste la herramienta.",keyTakeaways:["Preguntar al dueño cuántas llamadas se le quedan sin coger.","Explicar el servicio como citas que entran sin llamar.","Separar tu precio del coste de la herramienta."],video:null},{id:"s5_l4",title:"S5.4 Revisar cada mes la agenda y las respuestas de WhatsApp de tus clientes con IA",duration:"8 min",tipo:"P",ia:!0,summary:"Haces la revisión mensual de un cliente: horarios, festivos, servicios nuevos y preguntas que la gente repite. Claude te ayuda a mejorar los mensajes con esas preguntas y a escribir el resumen del mes. Te llevas la lista de revisión para usarla con todos.",keyTakeaways:["Revisar agenda y mensajes con una lista de puntos.","Mejorar con Claude las respuestas con las preguntas nuevas.","Enviar al dueño un resumen corto de lo que has cambiado."],video:null}]},{id:"s6",ruta:"bx",number:"Servicio 6",icon:"ri-search-2-line",title:"Salir en Google en tu ciudad (SEO local)",description:"Aprendes a ayudar a un negocio a salir cuando alguien de su zona busca lo que vende: qué revisar, qué escribir con IA, cómo venderlo y qué hacer cada mes.",disponible:null,lessons:[{id:"s6_l1",title:"S6.1 Qué es salir en Google en tu ciudad y qué negocios lo necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué es el SEO local con un ejemplo: alguien escribe «fisioterapeuta en Zaragoza» y Google enseña unos negocios y otros no. Ves de qué depende salir ahí: la ficha, la web y las reseñas. Y a qué negocios les importa más: los que la gente busca cuando tiene una necesidad.",keyTakeaways:["Explicar qué es el SEO local sin palabras raras.","Decir las tres cosas que mira Google para enseñar un negocio.","Elegir negocios a los que la gente busca por necesidad."],video:null},{id:"s6_l2",title:"S6.2 Revisar una web y escribir páginas por servicio y por zona con IA",duration:"10 min",tipo:"P",ia:!0,summary:"Coges la web de un negocio de ejemplo y miras qué le falta para salir en las búsquedas de su ciudad. Con Claude haces la lista de lo que busca la gente y escribes una página para cada servicio y cada zona. Revisas que todo lo escrito sea verdad y útil.",keyTakeaways:["Hacer con Claude la lista de búsquedas de un negocio.","Escribir una página clara para cada servicio y cada zona.","Comprobar que la web y la ficha dicen los mismos datos."],video:null},{id:"s6_l3",title:"S6.3 Vender el SEO local: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a enseñarle al dueño, con su propio móvil, que su negocio no sale cuando lo buscan. Escuchas una conversación de ejemplo con una asesoría. Y ves cómo poner el precio como cuota mensual, explicando que es un trabajo de meses y sin prometer el primer puesto.",keyTakeaways:["Hacer la prueba de la búsqueda delante del dueño.","Explicar que los resultados tardan meses, sin asustar.","Poner una cuota mensual ligada al trabajo que entregas."],video:null},{id:"s6_l4",title:"S6.4 El trabajo mensual de SEO local: contenido nuevo e informe con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Montas la rutina del mes para cada cliente: una página o un artículo nuevo, la ficha al día y un repaso de las búsquedas. Claude te ayuda a escribir el contenido y a pasar los datos a un informe que se entiende. Así el cliente ve cada mes qué has hecho.",keyTakeaways:["Repetir cada mes las mismas tres tareas con cada cliente.","Escribir con Claude el contenido nuevo y revisarlo.","Hacer un informe mensual con pocas cifras y bien explicadas."],video:null}]},{id:"s7",ruta:"bx",number:"Servicio 7",icon:"ri-megaphone-line",title:"Anuncios para negocios locales",description:"Aprendes a llevar los anuncios de un negocio de tu zona: preparar la campaña con IA, venderlo con las cuentas claras y revisarlo cada mes sin vivir pegado a la pantalla.",disponible:null,lessons:[{id:"s7_l1",title:"S7.1 Qué es llevar los anuncios de un negocio local y cuáles lo necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué es llevar los anuncios de un negocio: pagar para salirle a la gente de su zona en Instagram, Facebook o Google. Ves la diferencia entre el dinero de los anuncios y lo que cobras tú. Y a qué negocios les compensa: los que ganan bastante con cada cliente nuevo, como una clínica dental o una empresa de reformas.",keyTakeaways:["Explicar qué es un anuncio de pago con un ejemplo de barrio.","Distinguir el dinero de los anuncios de lo que cobras tú.","Saber a qué negocios les salen las cuentas y a cuáles no."],video:null},{id:"s7_l2",title:"S7.2 Preparar la campaña de un negocio local con IA: público, textos e imágenes",duration:"10 min",tipo:"P",ia:!0,summary:"Preparas la campaña de un negocio de ejemplo antes de tocar la plataforma. Con Claude decides a quién enseñarle el anuncio, qué oferta poner y varios textos distintos para probar. Después ves cómo queda montada, con su zona y su presupuesto diario.",keyTakeaways:["Definir con Claude a quién va el anuncio y con qué oferta.","Escribir varios textos de anuncio para probar cuál funciona.","Montar la campaña con la zona y el presupuesto bien puestos."],video:null},{id:"s7_l3",title:"S7.3 Vender la gestión de anuncios: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a hacer con el dueño la cuenta sencilla: cuánto le deja un cliente nuevo y cuánto puede pagar por conseguirlo. Escuchas una reunión de ejemplo con una clínica. Y ves cómo poner tu precio como cuota fija al mes, aparte del dinero de los anuncios y sin garantizar resultados.",keyTakeaways:["Hacer con el dueño la cuenta de cuánto vale un cliente.","Explicar que el dinero de los anuncios lo paga el negocio.","Poner una cuota fija y dejar por escrito qué incluye."],video:null},{id:"s7_l4",title:"S7.4 Revisar las campañas y hacer el informe mensual de anuncios con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Montas la revisión semanal de las campañas con una lista corta: qué mirar, qué parar y qué dejar tranquilo. A final de mes le pasas los números a Claude y te devuelve un informe en palabras normales. Lo revisas, añades tu propuesta para el mes siguiente y lo envías.",keyTakeaways:["Revisar una campaña cada semana con una lista corta.","Convertir los números en un informe claro con Claude.","Proponer al cliente un cambio concreto para el mes siguiente."],video:null}]},{id:"s8",ruta:"bx",number:"Servicio 8",icon:"ri-robot-2-line",title:"Asistentes y automatizaciones con IA para empresas",description:"Aprendes a preparar asistentes con IA que quitan trabajo repetido a una empresa, a venderlos empezando por un problema concreto y a mantenerlos al día cada mes.",disponible:null,lessons:[{id:"s8_l1",title:"S8.1 Qué son los asistentes y las automatizaciones con IA y qué empresas los necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico qué es un asistente con IA: una IA preparada con los datos de una empresa para hacer siempre la misma tarea. Por ejemplo, redactar presupuestos, contestar correos repetidos o resumir reuniones. Ves qué empresas lo aprovechan más: las que tienen mucho papeleo, como asesorías, inmobiliarias o clínicas.",keyTakeaways:["Explicar qué es un asistente con IA con un ejemplo de oficina.","Encontrar tareas repetidas que la IA puede preparar.","Decir con claridad lo que la IA no hace sola."],video:null},{id:"s8_l2",title:"S8.2 Montar un asistente con IA para una empresa: instrucciones, documentos y pruebas",duration:"10 min",tipo:"P",ia:!0,summary:"Montas un asistente para una empresa de ejemplo dentro de Claude. Escribes sus instrucciones, le das los documentos que necesita y lo pruebas con casos reales del día a día. Corriges lo que falla hasta que las respuestas sirven, sabiendo que una persona siempre las revisa.",keyTakeaways:["Escribir las instrucciones de un asistente para una tarea concreta.","Darle los documentos de la empresa que necesita para acertar.","Probarlo con casos reales y corregir los fallos."],video:null},{id:"s8_l3",title:"S8.3 Vender asistentes con IA a empresas: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a vender esto sin hablar de tecnología: preguntas qué tarea les quita más horas cada semana. Escuchas una conversación de ejemplo con una asesoría. Y ves cómo poner el precio: un pago por dejar montado el primer asistente y una cuota mensual por mantenerlo y mejorarlo.",keyTakeaways:["Preguntar por la tarea que más tiempo quita a la empresa.","Ofrecer un primer asistente pequeño para empezar.","Poner el precio por el tiempo que ahorra, no por tus horas."],video:null},{id:"s8_l4",title:"S8.4 Mantener y mejorar cada mes los asistentes de tus clientes con IA",duration:"8 min",tipo:"P",ia:!0,summary:"Haces la revisión mensual de un asistente: recoges dónde ha fallado, actualizas sus documentos y mejoras las instrucciones. Con Claude preparas una guía de uso de una página para el equipo de la empresa. Y dejas apuntada la siguiente tarea que se puede automatizar.",keyTakeaways:["Recoger los fallos del mes con un mensaje fijo al cliente.","Actualizar las instrucciones y los documentos del asistente.","Escribir con Claude una guía de uso de una página."],video:null}]},{id:"s9",ruta:"bx",number:"Servicio 9",icon:"ri-phone-find-line",title:"Conseguir clientes para otros negocios (lo que hacemos en To Growth)",description:"Aprendes a convertir lo que has hecho en la Academia en un servicio: preparar para otro negocio su lista de empresas, sus mensajes y su seguimiento, venderlo y entregarlo cada mes.",disponible:null,lessons:[{id:"s9_l1",title:"S9.1 Qué es conseguir clientes para otros negocios y cuáles lo necesitan",duration:"7 min",tipo:"C",ia:!1,summary:"Te explico el servicio: a un negocio que vende a otras empresas le preparas la lista de a quién contactar, qué decir y cómo llevar la cuenta de cada contacto. Es lo mismo que has aprendido para ti, hecho para otro. Ves qué negocios lo necesitan: los que hacen bien su trabajo y solo esperan a que les recomienden.",keyTakeaways:["Explicar el servicio en una frase sin palabras raras.","Reconocer negocios que venden a empresas y solo viven de recomendaciones.","Decir qué partes del trabajo haces tú y cuáles el cliente."],video:null},{id:"s9_l2",title:"S9.2 Preparar la lista de empresas y los mensajes de un cliente con To Growth y Claude",duration:"10 min",tipo:"P",ia:!0,summary:"Trabajas para un cliente de ejemplo. En el Buscador de empresas sacas su lista por sector y ciudad y guardas las mejores. Con Claude escribes el guion de llamada y los mensajes con los datos de ese negocio, y dejas todo ordenado en el Organizador de llamadas.",keyTakeaways:["Sacar y guardar la lista de empresas de un cliente.","Escribir con Claude el guion y los mensajes de ese negocio.","Llevar cada contacto en el Organizador, columna a columna."],video:null},{id:"s9_l3",title:"S9.3 Vender la captación de clientes a otro negocio: a quién, qué decir y cómo poner el precio",duration:"8 min",tipo:"C",ia:!1,summary:"Aprendes a ofrecerlo usando el mismo método que vendes: lista, contacto y reunión. Escuchas una conversación de ejemplo con una empresa de limpieza de oficinas. Y ves cómo poner el precio como cuota mensual por un trabajo concreto, dejando claro quién hace los contactos y sin prometer un número de clientes.",keyTakeaways:["Usar tu propio método para conseguir a este cliente.","Acordar por escrito quién contacta y qué entregas tú.","Cobrar por el trabajo que haces, no por promesas de ventas."],video:null},{id:"s9_l4",title:"S9.4 El trabajo de cada mes: lista nueva, seguimiento e informe para tu cliente con IA",duration:"9 min",tipo:"P",ia:!0,summary:"Montas la rutina mensual de un cliente: lista nueva de empresas, repaso del Organizador de llamadas y mejora de los mensajes. Exportas los contactos y le pides a Claude un informe claro con lo que ha pasado y lo que toca. Así el cliente ve el trabajo aunque todavía no haya ventas.",keyTakeaways:["Renovar cada mes la lista de empresas del cliente.","Mejorar los mensajes con Claude según las respuestas.","Hacer un informe mensual a partir de los contactos exportados."],video:null}]}]})();
